INSERT OR IGNORE INTO products (id,name,category,description,material,price,stock,sizes,variants,reviews,created_at) VALUES ('a23f50f9-e104-488d-a27c-fb71887bdb03','Buso Algodón Perchado','Busos','Abrigo sin peso y estilo sin esfuerzo. Cuello redondo, puños y cintura en RIB que mantienen la forma, y nuestra montaña bordada en el pecho como firma discreta. Por dentro, algodón perchado suave que te acompaña desde la mañana fría hasta el último plan de la noche.','Algodón perchado de 280 gr con interior suave y cálido. Cuello, puños y cintura en tejido RIB. Logo de montaña bordado en el pecho.',100000,10,'["S", "M", "L", "XL"]','[{"colorName": "AZÚL OSCURO", "color": "#003461", "images": ["/catalogo/buzo-azul-1.webp", "/catalogo/buzo-azul-2.webp", "/catalogo/buzo-azul-3.webp", "/catalogo/buzo-azul-4.webp", "/catalogo/buzo-azul-5.webp"]}, {"colorName": "Lila", "color": "#8e7497", "images": ["/catalogo/buzo-lila-1.webp", "/catalogo/buzo-lila-2.webp", "/catalogo/buzo-lila-3.webp", "/catalogo/buzo-lila-4.webp", "/catalogo/buzo-lila-5.webp"]}, {"colorName": "NEGRO", "color": "#292a2c", "images": ["/catalogo/buzo-negro-1.webp", "/catalogo/buzo-negro-2.webp", "/catalogo/buzo-negro-3.webp", "/catalogo/buzo-negro-4.webp", "/catalogo/buzo-negro-5.webp"]}, {"colorName": "BEIGE", "color": "#ccb9a0", "images": ["/catalogo/buzo-beige-1.webp", "/catalogo/buzo-beige-2.webp", "/catalogo/buzo-beige-3.webp", "/catalogo/buzo-beige-4.webp", "/catalogo/buzo-beige-5.webp"]}, {"colorName": "ROJO", "color": "#a72b2c", "images": ["/catalogo/buzo-rojo-1.webp", "/catalogo/buzo-rojo-2.webp", "/catalogo/buzo-rojo-3.webp", "/catalogo/buzo-rojo-4.webp", "/catalogo/buzo-rojo-5.webp"]}, {"colorName": "CAFÉ", "color": "#664733", "images": ["/catalogo/buzo-cafe-1.webp", "/catalogo/buzo-cafe-2.webp", "/catalogo/buzo-cafe-3.webp", "/catalogo/buzo-cafe-4.webp", "/catalogo/buzo-cafe-5.webp"]}]','[]','2026-09-07T04:10:23.956Z');
INSERT OR IGNORE INTO products (id,name,category,description,material,price,stock,sizes,variants,reviews,created_at) VALUES ('e4e5acfa-02e8-47d4-9b12-0e03511c470f','Hoodies','Hoodies · Bordado digital','El que vas a querer usar todos los días. Capucha de doble capa que se sostiene sola, bolsillo canguro para las manos frías y cordones con herrete metálico que le dan el acabado premium. Al frente, nuestra montaña en bordado digital de alta precisión: CIENTOVEINTIUNO, hecho para llegar alto.','Algodón perchado de 400 gr, grueso y cálido, con interior suave en pelusa. Bordado digital con hilos de alta resistencia. Cordones de algodón trenzado con herretes metálicos.',120000,10,'["S", "M", "L", "XL", "XXL"]','[{"colorName": "LILA", "color": "#9f779c", "images": ["/catalogo/hoodies-1788834601752-wewoe9z.webp", "/catalogo/hoodies-1788834600927-srt6com.webp", "/catalogo/hoodies-1788834599618-wrv1xf3.webp", "/catalogo/hoodies-1788834722783-yzepnga.webp"]}, {"colorName": "NEGRO", "color": "#292a2c", "images": ["/catalogo/hoodie-negro-1.webp", "/catalogo/hoodie-negro-2.webp", "/catalogo/hoodie-negro-3.webp", "/catalogo/hoodie-negro-4.webp"]}, {"colorName": "BEIGE", "color": "#ccb9a0", "images": ["/catalogo/hoodie-beige-1.webp", "/catalogo/hoodie-beige-2.webp", "/catalogo/hoodie-beige-3.webp", "/catalogo/hoodie-beige-4.webp"]}, {"colorName": "ROJO", "color": "#a72b2c", "images": ["/catalogo/hoodie-rojo-1.webp", "/catalogo/hoodie-rojo-2.webp", "/catalogo/hoodie-rojo-3.webp", "/catalogo/hoodie-rojo-4.webp"]}, {"colorName": "CAFÉ", "color": "#664733", "images": ["/catalogo/hoodie-cafe-1.webp", "/catalogo/hoodie-cafe-2.webp", "/catalogo/hoodie-cafe-3.webp", "/catalogo/hoodie-cafe-4.webp"]}]','[{"author": "Sebastián P.", "rating": 5, "text": "El bordado es increíble, se nota la calidad del detalle. Abrió muy bien."}, {"author": "Valeria T.", "rating": 5, "text": "Es el mejor hoodie que he tenido, súper abrigado y el bordado no se desgasta."}]','2026-08-15T16:01:04.752Z');
